// makefun-autocorrect-20261127: the funniest autocorrect fail in one line.
// The program writes the line to /output/entry.txt (or $MAKEFUN_OUTPUT_DIR/entry.txt
// when run outside the grader). Node 22, standard library only, deterministic:
// the same constant is written on every run, so both grader runs produce the same
// bytes. The line is 114 characters, inside the 1-199 character gate, and the
// entry.txt beside this file is the same line, generated by running this program.
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const ENTRY = `Meant to text my wife "I'll pick up the kids" — autocorrect sent "I'll pick up the kittens". We now own four cats.
`;

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'entry.txt'), ENTRY, 'utf8');
